// 2 - Clean the Record: names, phone format, email and lead source
// A lead with no usable email stops here and reaches your error alert, so no blank person is ever created.
const titleCase = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ')
  .replace(/(^|[\s'-])\p{L}/gu, (m) => m.toUpperCase());
const toE164 = (p) => {
  const d = String(p || '').replace(/\D/g, '');
  if (d.length === 10) return '+1' + d;                      // US number without country code
  if (d.length === 11 && d.startsWith('1')) return '+' + d;
  return d ? '+' + d : '';
};
// Your lead sources, spelled one way in both CRMs. Add a line per source.
const SOURCES = {
  'facebook lead ad': 'Facebook Ads', 'facebook': 'Facebook Ads',
  'google ads': 'Google Ads', 'website form': 'Website', 'website': 'Website',
  'referral': 'Referral',
};

return $input.all().map(({ json }) => {
  const b = json.body || json;
  const cd = b.customData || {};
  const email = String(b.email || '').trim().toLowerCase();
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
    throw new Error(`No usable email on GHL contact ${b.contact_id}: "${b.email || ''}"`);
  }
  const first = titleCase(b.first_name);
  const last = titleCase(b.last_name);
  const rawSource = String(b.contact_source || b.source || '').trim();
  return { json: {
    ghl_contact_id: b.contact_id,
    ghl_opportunity_id: cd.opportunity_id || '',
    first_name: first,
    last_name: last,
    full_name: `${first} ${last}`.trim(),
    email,
    phone: toE164(b.phone),
    lead_source: SOURCES[rawSource.toLowerCase()] || rawSource || 'Unknown',
    ghl_stage: String(cd.stage_name || 'New Lead').trim(),
    lead_value: Number(cd.lead_value) || 0,
    pipedrive_deal_id: cd.pipedrive_deal_id ? Number(cd.pipedrive_deal_id) : null,
  } };
});

// 4 - Route by lead source: pick the owner, pipeline and stage
// A returning person keeps the rep who already owns them in Pipedrive.
const cfg = $('0 - Config: Your Settings').item.json;
const lead = $('2 - Clean the Record: Names, Phone Format, Email and Lead Source').item.json;

// Your lead sources -> the Pipedrive user who owns them (Pipedrive > Settings > Manage users)
const OWNER_BY_SOURCE = {
  'Facebook Ads': 'PASTE-YOUR-PIPEDRIVE-USER-ID-FOR-FACEBOOK-ADS',
  'Google Ads':   'PASTE-YOUR-PIPEDRIVE-USER-ID-FOR-GOOGLE-ADS',
  'Website':      'PASTE-YOUR-PIPEDRIVE-USER-ID-FOR-WEBSITE',
  'Referral':     'PASTE-YOUR-PIPEDRIVE-USER-ID-FOR-REFERRAL',
};
// Your GHL stage names -> the matching Pipedrive stage ids
const PIPEDRIVE_STAGE_BY_GHL_STAGE = {
  'New Lead':        'PASTE-YOUR-PIPEDRIVE-STAGE-ID-NEW-LEAD',
  'Contacted':       'PASTE-YOUR-PIPEDRIVE-STAGE-ID-CONTACTED',
  'Appointment Set': 'PASTE-YOUR-PIPEDRIVE-STAGE-ID-APPOINTMENT-SET',
  'Proposal Sent':   'PASTE-YOUR-PIPEDRIVE-STAGE-ID-PROPOSAL-SENT',
};

const match = (($json.data && $json.data.items) || [])[0];
const person = match ? match.item : null;

return { json: {
  ...lead,
  person_id: person ? person.id : null,
  owner_id: (person && person.owner && person.owner.id) || OWNER_BY_SOURCE[lead.lead_source] || cfg.pipedrive_default_owner_id,
  pipeline_id: cfg.pipedrive_pipeline_id,
  stage_id: PIPEDRIVE_STAGE_BY_GHL_STAGE[lead.ghl_stage] || PIPEDRIVE_STAGE_BY_GHL_STAGE['New Lead'],
  deal_title: `${lead.full_name} - ${lead.lead_source}`,
} };

// 11 - Reshape each existing GHL opportunity into the same lead record a new lead sends
// From here migrated leads run through the same cleaner, dedupe and routing as new ones.
// Your GHL stage ids -> stage names (GHL > Opportunities > Pipelines)
const GHL_STAGE_NAME_BY_ID = {
  'PASTE-YOUR-GHL-STAGE-ID-NEW-LEAD':        'New Lead',
  'PASTE-YOUR-GHL-STAGE-ID-CONTACTED':       'Contacted',
  'PASTE-YOUR-GHL-STAGE-ID-APPOINTMENT-SET': 'Appointment Set',
  'PASTE-YOUR-GHL-STAGE-ID-PROPOSAL-SENT':   'Proposal Sent',
};
const out = [];
for (const { json } of $input.all()) {
  for (const opp of json.opportunities || []) {
    const c = opp.contact || {};
    const [first, ...rest] = String(c.name || '').trim().split(/\s+/);
    out.push({ json: { body: {
      contact_id: c.id || opp.contactId,
      first_name: first || '',
      last_name: rest.join(' '),
      email: c.email || '',
      phone: c.phone || '',
      contact_source: opp.source || '',
      customData: {
        opportunity_id: opp.id,
        stage_name: GHL_STAGE_NAME_BY_ID[opp.pipelineStageId] || 'New Lead',
        lead_value: opp.monetaryValue || 0,
      },
    } } });
  }
}
return out;

// 13 - Match the Pipedrive stage to your GHL stage, skip our own echo
// Only real stage moves by a person continue. A move this sync made itself is dropped,
// so GHL and Pipedrive never bounce the same change back and forth.
const SYNC_USER_ID = 'PASTE-YOUR-PIPEDRIVE-API-USER-ID';     // the Pipedrive user whose API token n8n uses
const GHL_PIPELINE_ID = 'PASTE-YOUR-GHL-PIPELINE-ID';
const GHL_CONTACT_FIELD = 'PASTE-YOUR-GHL-CONTACT-ID-FIELD-KEY';        // Pipedrive deal custom field keys
const GHL_OPPORTUNITY_FIELD = 'PASTE-YOUR-GHL-OPPORTUNITY-ID-FIELD-KEY';
// Your Pipedrive stage ids -> the GHL stage that fires the matching follow-up workflow
const GHL_STAGE_BY_PIPEDRIVE_STAGE = {
  'PASTE-YOUR-PIPEDRIVE-STAGE-ID-CONTACTED':       { ghl: 'PASTE-YOUR-GHL-STAGE-ID-CONTACTED', name: 'Contacted' },
  'PASTE-YOUR-PIPEDRIVE-STAGE-ID-APPOINTMENT-SET': { ghl: 'PASTE-YOUR-GHL-STAGE-ID-APPOINTMENT-SET', name: 'Appointment Set' },
  'PASTE-YOUR-PIPEDRIVE-STAGE-ID-PROPOSAL-SENT':   { ghl: 'PASTE-YOUR-GHL-STAGE-ID-PROPOSAL-SENT', name: 'Proposal Sent' },
};
const field = (deal, key) => {
  const v = (deal.custom_fields || {})[key];
  return v && typeof v === 'object' ? v.value : v;
};

const out = [];
for (const { json } of $input.all()) {
  const b = json.body || json;
  const meta = b.meta || {};
  const deal = b.data || {};
  const prev = b.previous || {};
  if (meta.entity !== 'deal' || meta.action !== 'change') continue;
  if (prev.stage_id === undefined || prev.stage_id === deal.stage_id) continue;   // not a stage move
  if (String(meta.user_id) === String(SYNC_USER_ID)) continue;                      // our own update coming back
  const target = GHL_STAGE_BY_PIPEDRIVE_STAGE[String(deal.stage_id)];
  const opportunityId = field(deal, GHL_OPPORTUNITY_FIELD);
  if (!target || !opportunityId) continue;
  out.push({ json: {
    deal_id: deal.id,
    person_id: deal.person_id,
    owner_id: deal.owner_id,
    ghl_contact_id: field(deal, GHL_CONTACT_FIELD),
    ghl_opportunity_id: opportunityId,
    ghl_pipeline_id: GHL_PIPELINE_ID,
    ghl_stage_id: target.ghl,
    stage_name: target.name,
    moved_by_user_id: meta.user_id,
  } });
}
return out;

